{"hypotheses": [
  {
    "name": "Patent-Adjusted Organizational Capital",
    "mechanism": "Firms with high organizational capital (OrgCap) and high patent intensity relative to R&D (PatentsRD) are likely to possess unique, defensible business processes not captured by standard intangibles. Adjusting for R&D ability (RDAbility) further filters out firms that spend heavily but inefficiently, focusing the composite on efficiently innovative organizations with sustainable advantages.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OrgCap"},
        {"weight": 0.5, "primitive": "PatentsRD"},
        {"weight": -0.5, "primitive": "RDAbility"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.70,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Customer Momentum with Supplier Discount",
    "mechanism": "Firms with strong customer momentum (iomom_cust) but weak supplier momentum (iomom_supp) are likely to be benefiting from end-market demand not driven by supply chain effects. Subtracting supplier momentum isolates firms whose demand is idiosyncratic and less likely to be a function of cyclical supply chain boosts, leading to persistent outperformance.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "iomom_cust"},
        {"weight": -1.0, "primitive": "iomom_supp"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "correlation", "primitive": "iomom_cust", "bound": "below", "threshold": 0.3},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.55,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Deferred Revenue Growth Efficiency",
    "mechanism": "Firms growing deferred revenue (DelDRC) while simultaneously improving asset turnover (ChAssetTurnover) and avoiding excessive working capital expansion (ChNWC) are monetizing future sales without straining liquidity. The composite identifies efficient revenue recognition and customer prepayment as a sign of high business quality, which is not captured by simple growth or quality screens.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "DelDRC"},
        {"weight": 0.5, "primitive": "ChAssetTurnover"},
        {"weight": -0.5, "primitive": "ChNWC"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "subperiod_consistency"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "DelDRC", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.60,
    "expected_decay_half_life_months": 40
  },
  {
    "name": "Real Estate Tangibility Premium",
    "mechanism": "Firms with high real estate holdings (realestate) and asset tangibility (tang), but low book leverage (BookLeverage), are able to collateralize assets without the risk of distress, enabling them to access cheap credit and weather downturns. The composite captures a premium for underexploited tangible assets, uncorrelated with generic value or leverage effects.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "realestate"},
        {"weight": 0.5, "primitive": "tang"},
        {"weight": -1.0, "primitive": "BookLeverage"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "BM", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Ownership Breadth with Analyst Revision",
    "mechanism": "Stocks with increasing breadth of ownership (DelBreadth) and positive analyst forecast revisions (AnalystRevision), but low consensus recommendation upgrades (ConsRecomm), are benefiting from genuinely improving fundamentals that are underappreciated by the market. The composite exploits slow diffusion of information across investor types, distinct from attention or analyst effects.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "DelBreadth"},
        {"weight": 1.0, "primitive": "AnalystRevision"},
        {"weight": -0.5, "primitive": "ConsRecomm"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "correlation", "primitive": "AnalystRevision", "bound": "below", "threshold": 0.3},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"}
    ],
    "expected_annualized_sharpe": 0.50,
    "expected_decay_half_life_months": 20
  },
  {
    "name": "Share Turnover Volatility Arbitrage",
    "mechanism": "Firms with high share turnover volatility (std_turn) and high option trading volume (OptionVolume2), but low probability of informed trading (ProbInformedTrading), attract liquidity traders rather than informed traders. This composite captures excess volatility-driven mispricings, unexploited by traditional volume or illiquidity factors, especially attractive for contrarian strategies.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "std_turn"},
        {"weight": 0.5, "primitive": "OptionVolume2"},
        {"weight": -1.0, "primitive": "ProbInformedTrading"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "correlation", "primitive": "Illiquidity", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.60,
    "expected_decay_half_life_months": 14
  },
  {
    "name": "Tax-Efficient Cash Flow Premium",
    "mechanism": "Firms with high cash flow to market (CF), high taxable income proportion (Tax), and low excluded expenses (ExclExp) are realizing strong operational performance with tax efficiency, signaling sustainable real earnings. By penalizing excluded expenses, the composite avoids accounting-driven artificial profitability and focuses on firms with genuine after-tax cash generation.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "CF"},
        {"weight": 0.5, "primitive": "Tax"},
        {"weight": -1.0, "primitive": "ExclExp"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "subperiod_consistency"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 60
  },
  {
    "name": "Market-Downside Franchise Resilience",
    "mechanism": "During down equity markets (MKT_TRAILING_12M_DOWN), firms with high brand capital investment (BrandInvest) and strong cash productivity (CashProd) but low short interest (ShortInterest) are likely to display franchise resilience. This composite isolates downside protection from established customer loyalty and operational strength, excluding crowded short risk.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "BrandInvest"},
        {"weight": 1.0, "primitive": "CashProd"},
        {"weight": -1.0, "primitive": "ShortInterest"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "BrandInvest", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.45,
    "expected_decay_half_life_months": 48
  }
]}
